1	"use client";
2	
3	import { useCallback, useEffect, useState } from "react";
4	import { adminNotes } from "@/lib/adminApi";
5	import type { Note, NoteColor } from "@/types";
6	import NoteCard from "./NoteCard";
7	import styles from "./NotesPanel.module.css";
8	
9	interface Props {
10	  /** Exactly one of storyId / chapterId must be set. */
11	  storyId?: string;
12	  chapterId?: string;
13	}
14	
15	/**
16	 * Persistent right-column notes panel on the story / chapter editor.
17	 * Multiple color-coded note cards, one expanded at a time, with an
18	 * "+ Add note" action. Replaces the legacy single-textarea NotesDrawer.
19	 *
20	 * On wide screens the panel sits inline in the page's grid. Under
21	 * 1100px it collapses into a floating button (bottom-right) that
22	 * slides the panel in as an overlay sheet. The internal `mobileOpen`
23	 * state controls the sheet — it's a no-op on desktop because the CSS
24	 * forces the panel visible there regardless.
25	 */
26	export default function NotesPanel({ storyId, chapterId }: Props) {
27	  const [notes, setNotes] = useState<Note[]>([]);
28	  const [loading, setLoading] = useState(true);
29	  const [error, setError] = useState<string | null>(null);
30	  const [expandedId, setExpandedId] = useState<string | null>(null);
31	  const [mobileOpen, setMobileOpen] = useState(false);
32	  const [busy, setBusy] = useState(false);
33	
34	  // Initial fetch — re-runs if the owner id changes (e.g., editing
35	  // a different chapter in the same series flow). The setState calls
36	  // before the async fetch are an intentional reset-to-loading; the
37	  // react-hooks/set-state-in-effect rule (added in a recent plugin
38	  // bump) flags this pattern, but it's the same shape used elsewhere
39	  // in the codebase (see CommandPalette, AgeGate).
40	  useEffect(() => {
41	    let cancelled = false;
42	    // eslint-disable-next-line react-hooks/set-state-in-effect
43	    setLoading(true);
44	    setError(null);
45	    adminNotes
46	      .list({ storyId, chapterId })
47	      .then((data) => {
48	        if (cancelled) return;
49	        setNotes(data);
50	      })
51	      .catch((e: unknown) => {
52	        if (cancelled) return;
53	        setError(e instanceof Error ? e.message : "Failed to load notes");
54	      })
55	      .finally(() => {
56	        if (!cancelled) setLoading(false);
57	      });
58	    return () => {
59	      cancelled = true;
60	    };
61	  }, [storyId, chapterId]);
62	
63	  const addNote = useCallback(async () => {
64	    if (busy) return;
65	    setBusy(true);
66	    try {
67	      const created = await adminNotes.create({
68	        storyId,
69	        chapterId,
70	        color: "GOLD",
71	      });
72	      setNotes((prev) => [...prev, created]);
73	      setExpandedId(created.id);
74	    } catch (e: unknown) {
75	      setError(e instanceof Error ? e.message : "Failed to add note");
76	    } finally {
77	      setBusy(false);
78	    }
79	  }, [busy, storyId, chapterId]);
80	
81	  const updateNote = useCallback(
82	    async (
83	      id: string,
84	      patch: { title?: string; body?: string; color?: NoteColor },
85	    ) => {
86	      // Optimistic — apply locally first so typing/color clicks feel
87	      // instant; the server's response is the authoritative version
88	      // and overwrites in case of normalization.
89	      setNotes((prev) =>
90	        prev.map((n) => (n.id === id ? { ...n, ...patch } : n)),
91	      );
92	      try {
93	        const updated = await adminNotes.update(id, patch);
94	        setNotes((prev) => prev.map((n) => (n.id === id ? updated : n)));
95	      } catch (e: unknown) {
96	        setError(e instanceof Error ? e.message : "Failed to save note");
97	      }
98	    },
99	    [],
100	  );
101	
102	  const deleteNote = useCallback(
103	    async (id: string) => {
104	      const removed = notes.find((n) => n.id === id);
105	      // Optimistic remove; on failure, re-insert at its original index.
106	      const idx = notes.findIndex((n) => n.id === id);
107	      setNotes((prev) => prev.filter((n) => n.id !== id));
108	      if (expandedId === id) setExpandedId(null);
109	      try {
110	        await adminNotes.remove(id);
111	      } catch (e: unknown) {
112	        if (removed) {
113	          setNotes((prev) => {
114	            const next = prev.slice();
115	            next.splice(idx, 0, removed);
116	            return next;
117	          });
118	        }
119	        setError(e instanceof Error ? e.message : "Failed to delete note");
120	      }
121	    },
122	    [notes, expandedId],
123	  );
124	
125	  return (
126	    <>
127	      <aside
128	        className={`${styles.panel} ${mobileOpen ? styles.mobileOpen : ""} ${
129	          expandedId ? styles.hasExpanded : ""
130	        }`}
131	        aria-label="Notes"
132	      >
133	        <header className={styles.header}>
134	          <h3 className={styles.title}>Notes</h3>
135	          {/* Mobile-only close — hidden via CSS on wide screens. */}
136	          <button
137	            type="button"
138	            onClick={() => setMobileOpen(false)}
139	            className={styles.closeMobile}
140	            aria-label="Close notes"
141	          >
142	            <CrossGlyph />
143	          </button>
144	        </header>
145	
146	        <div className={styles.list}>
147	          {error && <p className={styles.error}>{error}</p>}
148	          {loading && notes.length === 0 && (
149	            <p className={styles.empty}>Loading notes…</p>
150	          )}
151	          {!loading && notes.length === 0 && !error && (
152	            <p className={styles.empty}>No notes yet. Add one below.</p>
153	          )}
154	          {notes.map((note) => (
155	            <NoteCard
156	              key={note.id}
157	              note={note}
158	              expanded={expandedId === note.id}
159	              onExpand={() => setExpandedId(note.id)}
160	              onCollapse={() => setExpandedId(null)}
161	              onChange={(patch) => void updateNote(note.id, patch)}
162	              onDelete={() => void deleteNote(note.id)}
163	            />
164	          ))}
165	        </div>
166	
167	        <button
168	          type="button"
169	          onClick={() => void addNote()}
170	          disabled={busy}
171	          className={styles.addBtn}
172	        >
173	          + Add note
174	        </button>
175	      </aside>
176	
177	      {/* Mobile-only floating trigger — fixed bottom-right, hidden on
178	          wide screens via CSS. Carries a dot when notes exist so the
179	          writer knows the panel has content even when closed. */}
180	      <button
181	        type="button"
182	        onClick={() => setMobileOpen(true)}
183	        className={styles.mobileFab}
184	        aria-label="Open notes"
185	        title="Notes"
186	      >
187	        <NotesGlyph />
188	        <span>Notes</span>
189	        {notes.length > 0 && (
190	          <span className={styles.fabBadge} aria-hidden="true">
191	            {notes.length}
192	          </span>
193	        )}
194	      </button>
195	
196	      {/* Scrim behind the mobile sheet — hidden on desktop and when
197	          the sheet is closed. */}
198	      {mobileOpen && (
199	        <div
200	          className={styles.scrim}
201	          onPointerDown={() => setMobileOpen(false)}
202	          aria-hidden="true"
203	        />
204	      )}
205	    </>
206	  );
207	}
208	
209	function NotesGlyph() {
210	  return (
211	    <svg
212	      viewBox="0 0 24 24"
213	      width="16"
214	      height="16"
215	      fill="none"
216	      stroke="currentColor"
217	      strokeWidth="1.75"
218	      strokeLinecap="round"
219	      strokeLinejoin="round"
220	      aria-hidden="true"
221	      suppressHydrationWarning
222	    >
223	      <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
224	      <polyline points="14 2 14 8 20 8" />
225	      <line x1="8" y1="13" x2="16" y2="13" />
226	      <line x1="8" y1="17" x2="14" y2="17" />
227	    </svg>
228	  );
229	}
230	
231	function CrossGlyph() {
232	  return (
233	    <svg
234	      viewBox="0 0 24 24"
235	      width="16"
236	      height="16"
237	      fill="none"
238	      stroke="currentColor"
239	      strokeWidth="1.75"
240	      strokeLinecap="round"
241	      strokeLinejoin="round"
242	      aria-hidden="true"
243	      suppressHydrationWarning
244	    >
245	      <line x1="18" y1="6" x2="6" y2="18" />
246	      <line x1="6" y1="6" x2="18" y2="18" />
247	    </svg>
248	  );
249	}
