1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import type { Note, NoteColor } from "@/types";
5	import styles from "./NoteCard.module.css";
6	
7	// The six colors offered in the picker. Order = display order in the
8	// swatch row. Each carries a visible label so color is never the only
9	// signal (a11y: color-not-only). The CSS module maps each value to a
10	// background via [data-color="…"].
11	export const NOTE_COLORS: { value: NoteColor; label: string }[] = [
12	  { value: "GOLD", label: "Gold" },
13	  { value: "CRIMSON", label: "Crimson" },
14	  { value: "SAGE", label: "Sage" },
15	  { value: "INDIGO", label: "Indigo" },
16	  { value: "AMBER", label: "Amber" },
17	  { value: "SLATE", label: "Slate" },
18	];
19	
20	const AUTOSAVE_DEBOUNCE_MS = 600;
21	
22	interface Props {
23	  note: Note;
24	  expanded: boolean;
25	  onExpand: () => void;
26	  onCollapse: () => void;
27	  /** Patch is sent after a short debounce when title/body change, and
28	   *  immediately when color changes. */
29	  onChange: (patch: { title?: string; body?: string; color?: NoteColor }) => void;
30	  onDelete: () => void;
31	}
32	
33	/**
34	 * One note in the editor's NotesPanel.
35	 *
36	 * Collapsed: a pill — color dot + truncated title + 3-dot menu.
37	 * Expanded: title input + multi-line body textarea + 3-dot menu.
38	 *
39	 * Only one card is ever expanded in the panel at a time — the parent
40	 * tracks `expandedId`. Autosave is debounced per-field; color changes
41	 * patch immediately.
42	 */
43	export default function NoteCard({
44	  note,
45	  expanded,
46	  onExpand,
47	  onCollapse,
48	  onChange,
49	  onDelete,
50	}: Props) {
51	  // Local mirror so typing feels immediate. The server-side note may
52	  // arrive back with merged updates; we re-sync when the prop changes
53	  // and the local value matches what we last sent.
54	  const [title, setTitle] = useState(note.title);
55	  const [body, setBody] = useState(note.body);
56	  const [menuOpen, setMenuOpen] = useState(false);
57	  const lastSentTitle = useRef(note.title);
58	  const lastSentBody = useRef(note.body);
59	  const menuRef = useRef<HTMLDivElement>(null);
60	
61	  // Re-sync from upstream when the server's idea of the note changes
62	  // (e.g., after a color change PATCH returns) AND we haven't typed
63	  // newer characters locally. Without this, the input would silently
64	  // revert; without the lastSent check, the user's in-flight edits
65	  // would be clobbered by the server echo.
66	  useEffect(() => {
67	    if (title === lastSentTitle.current) setTitle(note.title);
68	    // eslint-disable-next-line react-hooks/exhaustive-deps
69	  }, [note.title]);
70	  useEffect(() => {
71	    if (body === lastSentBody.current) setBody(note.body);
72	    // eslint-disable-next-line react-hooks/exhaustive-deps
73	  }, [note.body]);
74	
75	  // Debounced PATCH for title.
76	  useEffect(() => {
77	    if (title === note.title) return;
78	    const t = setTimeout(() => {
79	      lastSentTitle.current = title;
80	      onChange({ title });
81	    }, AUTOSAVE_DEBOUNCE_MS);
82	    return () => clearTimeout(t);
83	    // eslint-disable-next-line react-hooks/exhaustive-deps
84	  }, [title]);
85	
86	  // Debounced PATCH for body.
87	  useEffect(() => {
88	    if (body === note.body) return;
89	    const t = setTimeout(() => {
90	      lastSentBody.current = body;
91	      onChange({ body });
92	    }, AUTOSAVE_DEBOUNCE_MS);
93	    return () => clearTimeout(t);
94	    // eslint-disable-next-line react-hooks/exhaustive-deps
95	  }, [body]);
96	
97	  // Close the menu on outside click / Esc.
98	  useEffect(() => {
99	    if (!menuOpen) return;
100	    const onPointer = (e: PointerEvent) => {
101	      const target = e.target as Node | null;
102	      if (target && menuRef.current?.contains(target)) return;
103	      setMenuOpen(false);
104	    };
105	    const onKey = (e: KeyboardEvent) => {
106	      if (e.key === "Escape") setMenuOpen(false);
107	    };
108	    document.addEventListener("pointerdown", onPointer);
109	    window.addEventListener("keydown", onKey);
110	    return () => {
111	      document.removeEventListener("pointerdown", onPointer);
112	      window.removeEventListener("keydown", onKey);
113	    };
114	  }, [menuOpen]);
115	
116	  const colorLabel =
117	    NOTE_COLORS.find((c) => c.value === note.color)?.label ?? "Gold";
118	  const displayTitle = title.trim() || "Untitled note";
119	
120	  const menu = (
121	    <div ref={menuRef} className={styles.menuWrap}>
122	      <button
123	        type="button"
124	        onClick={(e) => {
125	          e.stopPropagation();
126	          setMenuOpen((v) => !v);
127	        }}
128	        className={styles.menuBtn}
129	        aria-label="Note actions"
130	        aria-haspopup="menu"
131	        aria-expanded={menuOpen}
132	      >
133	        <DotsGlyph />
134	      </button>
135	      {menuOpen && (
136	        <div role="menu" className={styles.menuPanel}>
137	          <p className={styles.menuLabel}>Color</p>
138	          <div className={styles.swatchRow}>
139	            {NOTE_COLORS.map((c) => (
140	              <button
141	                key={c.value}
142	                type="button"
143	                onClick={() => {
144	                  onChange({ color: c.value });
145	                  setMenuOpen(false);
146	                }}
147	                className={`${styles.swatch} ${
148	                  c.value === note.color ? styles.swatchActive : ""
149	                }`}
150	                data-color={c.value}
151	                aria-label={`Color: ${c.label}`}
152	                title={c.label}
153	              >
154	                {c.value === note.color && <CheckGlyph />}
155	              </button>
156	            ))}
157	          </div>
158	          <button
159	            type="button"
160	            role="menuitem"
161	            onClick={() => {
