1	/* One note in the admin NotesPanel.
2	   The data-color attribute on .card maps to --note-color so the dot
3	   and accents pick up the right tone automatically.
4	
5	   Palette tuned for the dark canvas — muted, dim-glow, literary. */
6	
7	.card {
8	  --note-color: var(--gold);
9	  position: relative;
10	  display: flex;
11	  flex-direction: column;
12	  background: var(--bg-surface);
13	  border: 1px solid var(--border-line);
14	  border-radius: var(--radius-md-app);
15	  font-family: var(--font-ui);
16	  /* Per-property transitions so hover/active/swap each feel right
17	     instead of one blanket ease that drags everything along. */
18	  transition:
19	    border-color var(--transition-fast),
20	    transform 180ms cubic-bezier(0.16, 1, 0.3, 1),
21	    box-shadow 220ms cubic-bezier(0.16, 1, 0.3, 1);
22	}
23	
24	.card[data-color="GOLD"]    { --note-color: var(--gold); }
25	.card[data-color="CRIMSON"] { --note-color: #c4584c; }
26	.card[data-color="SAGE"]    { --note-color: #7fa17b; }
27	.card[data-color="INDIGO"]  { --note-color: #7e8ed1; }
28	.card[data-color="AMBER"]   { --note-color: #d99a4a; }
29	.card[data-color="SLATE"]   { --note-color: #8a8e97; }
30	
31	/* ── Collapsed pill ────────────────────────────────────────────── */
32	.collapsed {
33	  flex-direction: row;
34	  align-items: center;
35	  gap: 4px;
36	  padding: 4px 6px 4px 12px;
37	  border-radius: var(--radius-pill);
38	}
39	.collapsed:hover {
40	  border-color: var(--note-color);
41	  /* Small lift + soft glow keyed to the note's color — feels alive
42	     under the cursor without being noisy. */
43	  transform: translateY(-1px);
44	  box-shadow: 0 6px 14px -8px color-mix(in srgb, var(--note-color) 55%, transparent);
45	}
46	.collapsed:active {
47	  transform: translateY(0) scale(0.995);
48	  box-shadow: none;
49	}
50	
51	.pillBody {
52	  display: inline-flex;
53	  align-items: center;
54	  gap: 10px;
55	  flex: 1 1 auto;
56	  min-width: 0;
57	  background: transparent;
58	  border: 0;
